from verl.utils.reward_score.math_dapo import compute_score


def score(data_source, solution_str, ground_truth, extra_info):
    return float(compute_score(solution_str, ground_truth, strict_box_verify=True)["score"] > 0)

arguments.command:
python -I - <<'PY'
import json
from pathlib import Path
for name in ['generation_records/heldout-responses.json', 'generation_records/engine-requests.json']:
 d=json.loads(Path(name).read_text())
 print(name, type(d).__name__)
 if isinstance(d,dict):
  print('top keys',list(d))
  for k,v in d.items():
   print(k, type(v).__name__, len(v) if hasattr(v,'__len__') else v)
   if isinstance(v,list) and v: print('entry keys',list(v[0]) if isinstance(v[0],dict) else type(v[0]).__name__)
   elif isinstance(v,dict): print('subkeys',list(v)[:50])
 elif isinstance(d,list):
  print('length',len(d),'entry keys',list(d[0]))
for name in ['experiment_logs/rollouts/1.gen_001.jsonl','experiment_logs/validation/0.jsonl']:
 row=json.loads(Path(name).read_text().splitlines()[0])
 print(name,'keys',list(row))
 for k,v in row.items(): print(k,repr(v)[:600])
PY

