arguments.command:
python -I - <<'PY'
import pyarrow.parquet as pq
for path in ['assets/split/train.parquet','assets/split/validation.parquet']:
 t=pq.read_table(path)
 print('\n',path,t.num_rows,t.schema)
 for i,row in enumerate(t.to_pyrows()):
  print('ROW',i)
  for k,v in row.items(): print(k,repr(v)[:3500])
PY

