# direct name lookup therefore cannot verify the attention and MLP projections
# that dominate the model.  Keep the source order identical to vLLM's
# ``packed_modules_mapping`` so each source can be compared with its slice in
# the packed target parameter after ``load_weights`` returns.
_PACKED_WEIGHT_SYNC_PROBES = {
    "model.layers.0.self_attn.q_proj.weight": (
        "model.layers.0.self_attn.qkv_proj.weight",
