def _sample_tensor_fingerprint(tensor: torch.Tensor, *, points: int = 17) -> list[float]:
    flat = tensor.detach().reshape(-1)
    if flat.numel() == 0:
        return []
    count = min(points, flat.numel())
    if count == 1:
        indices = torch.zeros(1, dtype=torch.long, device=flat.device)
    else:
        indices = torch.arange(count, dtype=torch.long, device=flat.device)
        indices = indices * (flat.numel() - 1) // (count - 1)
    # vLLM rollout weights are bf16 in the OpenOPD recipes.  Round the actor
    # source through bf16 so a fp32 actor does not create false mismatches.
    return flat[indices].to(dtype=torch.bfloat16).float().cpu().tolist()


def _load_weights_with_optional_verification(model, weights, *, enabled: bool):
    # Every weight sync funnels through here -- both VllmRollout.update_weights
    # entry points call it.  Job 23937 proved the sharding manager's
    # update_params is *not* on this path: its NVFP4 branch never logged while
    # the engine-construction branch did, and BF16 weights reached vLLM's
    # default_weight_loader and asserted on shape.  So the re-quantization hook
    # belongs here, at the funnel, not there.
    if os.environ.get("QAT_NVFP4_ROLLOUT", "0") == "1":
        from opqad.integrations.nvfp4_rollout import plan_resync, resync_and_load

        plan = getattr(model, "_qat_nvfp4_plan", None)
        if plan is None:
            plan = plan_resync(model)
            model._qat_nvfp4_plan = plan
            logger.warning(
                "NVFP4 rollout re-sync planned for %d layers", len(plan)
            )
        return resync_and_load(model, weights, plan)

    if os.environ.get("QAT_STATEQUANT_FORMAL", "0") == "1":
        from opqad.integrations.statequant_rollout import load_and_verify_weights
        return load_and_verify_weights(model, weights)

    if not enabled:
        return model.load_weights(weights)

    source_fingerprints: dict[str, list[float]] = {}
    source_shapes: dict[str, tuple[int, ...]] = {}
    source_count = 0

    def tracked_weights():
        nonlocal source_count
        for name, tensor in weights:
            source_count += 1
            if name in _WEIGHT_SYNC_PROBE_NAMES or name in _PACKED_WEIGHT_SYNC_PROBES:
                if not isinstance(tensor, torch.Tensor):
                    raise TypeError(f"weight-sync probe expected Tensor for {name}, got {type(tensor)!r}")
                source_fingerprints[name] = _sample_tensor_fingerprint(tensor)
                source_shapes[name] = tuple(tensor.shape)
            yield name, tensor

    loaded = model.load_weights(tracked_weights())
    loaded_names = set(loaded) if loaded is not None else set()
    target_params = dict(model.named_parameters())
    comparisons = {}
    for name, source_values in source_fingerprints.items():
        target = target_params.get(name)
        if target is None:
            comparisons[name] = {"status": "target_missing"}
            continue
        target_values = _sample_tensor_fingerprint(target)
        if len(source_values) != len(target_values):
            comparisons[name] = {
                "status": "sample_size_mismatch",
                "source_points": len(source_values),
                "target_points": len(target_values),
            }
            continue
        max_abs = max(
            (abs(left - right) for left, right in zip(source_values, target_values, strict=True)), default=0.0
        )
        comparisons[name] = {"status": "ok" if max_abs == 0.0 else "mismatch", "max_abs": max_abs}

    for name, (target_name, source_group) in _PACKED_WEIGHT_SYNC_PROBES.items():
        if name not in source_fingerprints:
            continue
        missing_group = [source_name for source_name in source_group if source_name not in source_shapes]
        if missing_group:
            comparisons[name] = {"status": "packed_source_missing", "missing_sources": missing_group}
            continue
        target = target_params.get(target_name)
        if target is None:
            # Some vLLM model implementations consume the HF projection name
            # successfully but do not expose the packed runtime parameter via
            # ``named_parameters()`` after loading.  In that case the loader's
            # returned name set is the only authoritative acknowledgement that
            # this source tensor was consumed.  Do not turn that implementation
            # detail into a false verification failure; still fail closed when
            # neither the source nor packed target was reported as loaded.
            loaded_as = name if name in loaded_names else target_name if target_name in loaded_names else None
            comparisons[name] = (
                {"status": "loaded_uninspectable", "target": target_name, "loaded_as": loaded_as}
                if loaded_as is not None
                else {"status": "target_missing", "target": target_name}
            )
            continue
        source_shape = source_shapes[name]
        if not source_shape or target.ndim != len(source_shape) or tuple(target.shape[1:]) != source_shape[1:]:
            comparisons[name] = {
                "status": "packed_shape_mismatch",
                "source_shape": source_shape,
                "target_shape": tuple(target.shape),
            }
            continue
        offset = sum(source_shapes[source_name][0] for source_name in source_group[: source_group.index(name)])
        rows = source_shape[0]
        if offset + rows > target.shape[0]:
            comparisons[name] = {
                "status": "packed_slice_out_of_bounds",
                "offset": offset,
                "rows": rows,
                "target_shape": tuple(target.shape),
            }
            continue
        target_values = _sample_tensor_fingerprint(target.narrow(0, offset, rows))
        source_values = source_fingerprints[name]
        max_abs = max(
            (abs(left - right) for left, right in zip(source_values, target_values, strict=True)), default=0.0
        )
        comparisons[name] = {
            "status": "ok" if max_abs == 0.0 else "mismatch",
            "target": target_name,
            "offset": offset,
            "rows": rows,
            "max_abs": max_abs,
        }

    missing_sources = sorted(set(_WEIGHT_SYNC_PROBE_NAMES) - set(source_fingerprints))
    accepted_statuses = {"ok", "loaded_uninspectable"}
    failed = missing_sources or any(item.get("status") not in accepted_statuses for item in comparisons.values())
    report = {
        "source_weight_count": source_count,
        "loaded_weight_count": len(loaded) if loaded is not None else None,
        "missing_probe_sources": missing_sources,
        "source_fingerprints": source_fingerprints,
        "comparisons": comparisons,
    }
    logger.warning("OPENOPD_WEIGHT_SYNC_VERIFY %s", report)
    # Ray does not consistently forward module logger handlers from the hybrid
    # worker. stdout is captured reliably by the launcher and makes this diagnostic
    # visible before a validation-only job exits.
    print(f"OPENOPD_WEIGHT_SYNC_VERIFY {report}", flush=True)
    if failed:
        raise RuntimeError(f"actor -> vLLM weight synchronization verification failed: {report}")
    return loaded


