def _extract_rollout_topk(output_logprobs, response_ids, top_k: int):
    """Convert vLLM per-token logprob maps to sorted, fixed-width lists.

    vLLM includes the sampled token alongside the requested candidates.  The
    dict is therefore de-duplicated and sorted here rather than relying on
    insertion order.  Padding uses token id 0 and ``-inf``; the response mask
    excludes those positions downstream.
    """
    if top_k <= 0:
        raise ValueError(f"top_k must be positive, got {top_k}")
    output_logprobs = output_logprobs or []
    ids_rows = []
    logprob_rows = []
    for step, _ in enumerate(response_ids):
        entries = output_logprobs[step] if step < len(output_logprobs) else None
        ranked = []
        if entries:
            ranked = sorted(
                (
                    (int(token_id), float(lp.logprob))
                    for token_id, lp in entries.items()
                    if lp is not None and math.isfinite(float(lp.logprob))
                ),
                key=lambda item: item[1],
                reverse=True,
            )
        seen = set()
        unique = []
        for token_id, log_prob in ranked:
            if token_id in seen:
                continue
            seen.add(token_id)
            unique.append((token_id, log_prob))
            if len(unique) == top_k:
                break
        row_ids = [token_id for token_id, _ in unique]
        row_logprobs = [log_prob for _, log_prob in unique]
        row_ids.extend([0] * (top_k - len(row_ids)))
        row_logprobs.extend([float("-inf")] * (top_k - len(row_logprobs)))
        ids_rows.append(row_ids)

